const kick = (t, h) => `<div class="ltag" style="margin-top:24px">${t}</div><div class="mt" style="margin:3px 0 10px">${h}</div>`;
const tk = t => `<span class="lg" style="width:auto;min-width:42px;padding:0 6px;font-size:10px">${t}</span>`;
const hr = () => `<div style="height:1px;background:var(--a-line);margin:14px 0"></div>`;
const acc = (t, right) => `<div style="display:flex;align-items:center;gap:10px;padding:13px 0;border-top:1px solid var(--a-line)"><b class="sm" style="flex:1">${t}</b>${right || ''}${ic('i-next', 16)}</div>`;
/* Stufen-Leiter: Bild passt → Regel bestätigt → durchgerechnet */
const ladder = (a, b, c, dark) => `<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px">${[['Bild passt', a], ['Regel bestätigt', b], ['Durchgerechnet', c]].map(([t, v], i) => `<div style="border-radius:14px;padding:10px 9px;background:${i === 2 ? 'var(--lime)' : dark ? '#1c1c1c' : 'var(--a-card)'};color:${i === 2 ? '#000' : 'inherit'}"><div class="xs b" style="opacity:.7">${i + 1} · ${t}</div><div class="bb num" style="font-size:22px;margin-top:2px">${de(v, 0)}</div></div>`).join('')}</div>`;
/* Stufen-Balken je Methode (schwarz = Bild passt, grau-dunkel = Regel bestätigt, neongrün = durchgerechnet) */
const sbar = (r, mx) => { const w = v => (v / mx * 100).toFixed(1) + '%'; return `<div style="display:flex;height:8px;border-radius:9px;overflow:hidden;background:var(--a-line);margin-top:8px"><i style="width:${w(r[4])};background:var(--a-ink)"></i><i style="width:${w(r[5])};background:var(--a-mute)"></i><i style="width:${w(r[6])};background:var(--lime)"></i></div>`; };
const mcard = (r, mx, open) => `<div style="padding:12px 0;border-top:1px solid var(--a-line)"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px"><div style="min-width:0"><div class="bb">${r[0]}</div><div class="mu xs b">${r[1]} · ${r[2]}</div></div><div style="text-align:right"><div class="bb num" style="font-size:20px">${de(tot(r), 0)}</div><div class="mu xs">heute</div></div></div><div class="sm" style="margin-top:5px">${r[3]}</div>${sbar(r, mx)}${open || ''}</div>`;
/* Signal-Leiste: Stop · Einstieg · Schluss auf einer Linie */
const trk = (stop, entry, close) => { const lo = Math.min(stop, entry, close), hi = Math.max(stop, entry, close), X = v => 8 + (v - lo) / (hi - lo || 1) * 338; return `<svg width="354" height="26" style="display:block;margin-top:8px"><line x1="8" x2="346" y1="13" y2="13" stroke="var(--a-line)" stroke-width="6" stroke-linecap="round"/><line x1="${X(stop)}" x2="${X(close)}" y1="13" y2="13" stroke="#c8f531" stroke-width="6" stroke-linecap="round"/><circle cx="${X(stop)}" cy="13" r="6" fill="var(--a-ink)"/><rect x="${X(entry) - 1.5}" y="3" width="3" height="20" rx="1.5" fill="var(--a-ink)"/><circle cx="${X(close)}" cy="13" r="7" fill="#c8f531" stroke="var(--a-ink)" stroke-width="2.4"/></svg>`; };
const sig = (t, name, meth, st, stop, entry, close, luft, seit) => `<div style="padding:13px 0;border-top:1px solid var(--a-line)"><div style="display:flex;align-items:center;gap:10px">${tk(t)}<div style="flex:1;min-width:0"><b style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${name}</b><span class="mu xs b">${meth}</span></div>${st}</div>${trk(stop, entry, close)}<div style="display:flex;justify-content:space-between" class="xs b num"><span>Stop ${de(stop)} $</span><span class="mu">Einstieg ${de(entry)} $</span><span>Schluss ${de(close)} $</span></div><div style="display:flex;gap:8px;margin-top:8px;align-items:center"><span class="sm"><b class="num">${de(luft, 1)} %</b> Luft bis zum Stop</span><span style="margin-left:auto">${chg(seit)}</span></div></div>`;
const stp = (n, t, s) => `<div style="display:flex;gap:12px;padding:10px 0;border-top:1px solid var(--a-line)"><span style="flex:none;width:26px;height:26px;border-radius:50%;background:var(--a-ink);color:var(--a-inv);display:grid;place-items:center;font-weight:900;font-size:12px">${n}</span><div><b class="sm">${t}</b>${s ? `<div class="mu xs" style="margin-top:2px;line-height:1.4">${s}</div>` : ''}</div></div>`;
const st = (k, t) => vd(k, t);

